# ------------------------------------------------------------------ EA_SELLERIMG_V1 listing images
# Vivek, 20 Oct 2026: a seller puts images on their own listings from their AI without the image
# going through the chat as text. ChatGPT hands an attached file over as a download link
# (openai/fileParams); anywhere else the tool gives a one-time upload link for that SKU and slot.
# The image is prepared by Image Intelligence (trim or keep original - the seller chooses), staged,
# and sent to Amazon only with confirm "yes".

IMG_LINK_MIN = 60
IMG_LINK_UPLOADS = 10
IMG_SENDS_PER_DAY = 20


def _ii():
    import ea_img_intel as II
    return II


def _img_ensure(c):
    c.execute("CREATE TABLE IF NOT EXISTS seller_img_links (token_hash TEXT, seller_id INTEGER, sku TEXT, "
              "slot TEXT, mode TEXT, created_at TEXT, expires_at TEXT, uploads INTEGER)")


def _slot(v):
    s = re.sub(r'[^a-z0-9]', '', str(v or '').lower()).replace('image', '').replace('position', '')
    s = {'1': 'main', 'main': 'main', 'swatch': 'swatch', 'mainimage': 'main'}.get(s, s)
    if s in ('main', 'swatch') or s in ('2', '3', '4', '5', '6', '7', '8'):
        return s
    raise ValueError('Ask the seller which position this image is for: main, 2 to 8, or swatch.')


def _mode(v):
    m = str(v or '').strip().lower()
    if m in ('trim', 'original'):
        return m
    raise ValueError('Ask the seller first: trim the white margins around the product (trim), or keep the '
                     'image exactly as it is (original)? Then call again with mode.')


def _img_item(d, sid, sku):
    II = _ii()
    sku = str(sku or '').strip()
    if not sku:
        raise ValueError('Ask the seller which SKU or ASIN the image is for.')
    sids = II._sids(d, sid)
    it = II._item(d, sids, None, sku)
    if not it:
        r = d.execute("SELECT sku FROM listings_master WHERE seller_id IN (%s) AND upper(asin)=? "
                      "ORDER BY CASE WHEN status='Active' THEN 0 ELSE 1 END LIMIT 1" % II._ph(len(sids)),
                      tuple(sids) + (sku.upper(),)).fetchone()
        if r:
            it = II._item(d, sids, None, r[0])
    if not it:
        raise ValueError('%s is not one of this account\'s SKUs or ASINs - check it with my_products.' % sku)
    return it, sids


def _safe_url(u):
    import socket
    import ipaddress
    from urllib.parse import urlparse
    p = urlparse(str(u or ''))
    if p.scheme != 'https' or not p.hostname:
        raise ValueError('the image link must be an https link')
    for inf in socket.getaddrinfo(p.hostname, 443):
        ip = ipaddress.ip_address(inf[4][0])
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_multicast:
            raise ValueError('that image link cannot be used')


def _fetch(u):
    import urllib.request
    _safe_url(u)

    class _R(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, hdrs, newurl):
            _safe_url(newurl)
            return urllib.request.HTTPRedirectHandler.redirect_request(self, req, fp, code, msg, hdrs, newurl)

    op = urllib.request.build_opener(_R)
    r = op.open(urllib.request.Request(u, headers={'User-Agent': 'EA-OS-image'}), timeout=25)
    data = r.read(_ii().MAX_UPLOAD + 1)
    if len(data) > _ii().MAX_UPLOAD:
        raise ValueError('the file is over 30 MB')
    return data


def _new_img_link(sid, sku, slot, mode):
    k = 'im' + secrets.token_urlsafe(18).replace('-', 'x').replace('_', 'y')
    exp = (datetime.datetime.now() + datetime.timedelta(minutes=IMG_LINK_MIN)).strftime('%Y-%m-%d %H:%M:%S')
    c = _con()
    try:
        _img_ensure(c)
        c.execute("INSERT INTO seller_img_links (token_hash, seller_id, sku, slot, mode, created_at, expires_at, "
                  "uploads) VALUES (?,?,?,?,?,?,?,?)", (_hash(k), sid, sku, slot, mode, _now(), exp, 0))
        c.commit()
    finally:
        c.close()
    import ea_tasklist as TK
    return TK.APP_URL + '/s/img/' + k


def _img_link_row(k):
    if not k or len(k) < 20:
        return None
    c = _con()
    try:
        _img_ensure(c)
        c.commit()
        r = c.execute("SELECT seller_id, sku, slot, mode, expires_at, uploads FROM seller_img_links "
                      "WHERE token_hash=?", (_hash(k),)).fetchone()
    finally:
        c.close()
    if not r or str(r[4]) < _now() or int(r[5] or 0) >= IMG_LINK_UPLOADS:
        return None
    return {'sid': int(r[0]), 'sku': r[1], 'slot': r[2], 'mode': r[3], 'expires': r[4]}


def _img_link_used(k):
    c = _con()
    try:
        c.execute("UPDATE seller_img_links SET uploads=COALESCE(uploads,0)+1 WHERE token_hash=?", (_hash(k),))
        c.commit()
    finally:
        c.close()


def t_img_upload(sid, a):
    II = _ii()
    slot = _slot(a.get('slot'))
    d = II._db()
    try:
        II.ensure(d)
        it, sids = _img_item(d, sid, a.get('sku'))
        mode = _mode(a.get('mode'))
        f = a.get('image')
        if isinstance(f, list):
            f = f[0] if f else None
        url = (f or {}).get('download_url') if isinstance(f, dict) else None
        if not url:
            link = _new_img_link(sid, it['sku'], slot, mode)
            return {'sku': it['sku'], 'asin': it['asin'], 'position': II.LABEL[slot], 'mode': mode,
                    'upload_link': link,
                    'next': 'The image file could not come through this chat. Give the seller this upload link '
                            '(works for %d minutes) and ask them to pick the same photo there. When they say it is '
                            'uploaded, call image_status, show them the preview, and ask whether to send it.'
                            % IMG_LINK_MIN}
        r = II.stage(d, it, sids, slot, _fetch(url), mode == 'original', 'seller-ai')
    finally:
        d.close()
    return {'sku': it['sku'], 'asin': it['asin'], 'title': it['title'], 'position': II.LABEL[slot],
            'mode': mode, 'preview': r['url'], 'size': '%dx%d' % (r['w'], r['h']), 'notes': r['notes'],
            'next': 'Show the seller the preview link and the notes. Nothing is sent yet. If it looks right and '
                    'they say yes, call image_send with confirm "yes". If trimming cut part of the product, call '
                    'image_upload again with mode "original".'}


def t_img_status(sid, a):
    II = _ii()
    d = II._db()
    try:
        II.ensure(d)
        it, sids = _img_item(d, sid, a.get('sku'))
        rows = d.execute("SELECT slot, url, w, h, note, status, uploaded_at, sent_at, result FROM img_intel "
                         "WHERE seller_id=? AND sku=? AND expired IS NULL AND status<>'removed' ORDER BY slot",
                         (it['seller_id'], it['sku'])).fetchall()
        live = None
        if str(a.get('check_amazon') or '').lower() in ('yes', 'true', '1'):
            ok, live = II.check(d, it)
    finally:
        d.close()
    return {'sku': it['sku'], 'asin': it['asin'], 'title': it['title'],
            'images': [{'position': II.LABEL.get(r[0], r[0]), 'preview': r[1], 'size': '%sx%s' % (r[2], r[3]),
                        'notes': r[4], 'status': r[5], 'uploaded_at': r[6], 'sent_at': r[7], 'amazon': r[8]}
                       for r in rows],
            'amazon_now': live,
            'next': 'ready = waiting for the seller\'s yes, then image_send. sent = Amazon is processing - '
                    'call again with check_amazon "yes" in a few minutes.'}


def t_img_send(sid, a):
    if str(a.get('confirm') or '').strip().lower() != 'yes':
        raise ValueError('confirm must be "yes" - only after the seller has seen the preview and agreed')
    used = _today_count(sid, 'image_send')
    if used >= IMG_SENDS_PER_DAY:
        raise ValueError('daily limit: %d image sends a day through the AI link' % IMG_SENDS_PER_DAY)
    II = _ii()
    d = II._db()
    try:
        II.ensure(d)
        it, sids = _img_item(d, sid, a.get('sku'))
        ok, msg = II.send(d, it, 'seller-ai')
    finally:
        d.close()
    if not ok:
        raise ValueError(msg)
    return {'sku': it['sku'], 'sent': True, 'amazon': msg, '_n': 1,
            'next': 'Call image_status with check_amazon "yes" in about 5 minutes to see it on the listing.'}


